BEGIN;

CREATE TABLE dim_empresas (
empresa_id INTEGER NOT NULL,
cnpj VARCHAR(20) NOT NULL,
nome_empresa VARCHAR(300) NOT NULL,
setor VARCHAR(100) 
);



CREATE TABLE fato_financeiro (
fato_id INTEGER NOT NULL,
empresa_id INTEGER ,
tempo_id INTEGER ,
conta_id INTEGER ,
valor NUMERIC(20, 2) 
);



CREATE TABLE dim_tempo (
tempo_id INTEGER NOT NULL,
data_referencia DATE NOT NULL,
ano INTEGER NOT NULL
);



CREATE TABLE dim_contas (
conta_id INTEGER NOT NULL,
codigo_conta VARCHAR(50) NOT NULL,
nome_conta VARCHAR(300) NOT NULL,
tipo_demonstrativo VARCHAR(10) NOT NULL
);



COMMIT;
